export const A3ARM_TOTAL = A3ARM.length;

/* Números da extração, pra tela poder ser honesta sobre a cobertura. */
export const A3ARM_META = {
  dump: "Arma3_x64_2026-07-25_23-18-48.rpt",
  classesNoConfig: 10822,
  armasCanonicas: 1477,
  nucleo: 106,
  mods: 1371,
  nucleoComBalistica: 104,
  nucleoComIcone: 76,
  porTipo: { dmr: 12, fuzil: 43, lancador: 13, lmg: 10, pistola: 14, shotgun: 3, smg: 9, sniper: 2 },
  porEvidencia: { classe: 45, config: 23, "desc-generica": 2, descricao: 36 },
  arsenalUrl: '/arma3/armas-db.json',
};

/* Arsenal completo (mods) sob demanda. Uma requisição por sessão —
 * a promessa fica em cache no módulo. ~1,9 MB cru, ~100 kB no fio (gzip). */
let _arsenal = null;
export function carregarArsenal() {
  if (!_arsenal) {
    _arsenal = fetch(A3ARM_META.arsenalUrl)
      .then((r) => { if (!r.ok) throw new Error(`HTTP ${r.status}`); return r.json(); })
      .then((d) => d.armas)
      .catch((err) => { _arsenal = null; throw err; });
  }
  return _arsenal;
}
